/**
 * emit to subscription queries of type FindAgreement,
 * but only if the id matches
 *
 * @param		entity	Agreement
 */
	protected void emitFindAgreement( Agreement entity ) {
		LOGGER.info("handling emitFindAgreement" );
		
	    queryUpdateEmitter.emit(FindAgreementQuery.class,
	                            query -> query.getFilter().getAgreementId().equals(entity.getAgreementId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAgreement
	 * 
	 * @param		entity	Agreement
	 */
	protected void emitFindAllAgreement( Agreement entity ) {
		LOGGER.info("handling emitFindAllAgreement" );
		
	    queryUpdateEmitter.emit(FindAllAgreementQuery.class,
	                            query -> true,
	                            entity);
	}

